(482647, 46450, 6668, '<td valign="top">The book on the bottom of the shot ruins the photo for me, otherwise nice shot.</td>', 'The book on the bottom of the shot ruins the photo for me, otherwise nice shot.', '2003-11-12 15:11:17.000000', NULL, 1),
(482648, 46177, 10145, '<td valign="top">Funny!</td>', 'Funny!', '2003-11-12 15:11:31.000000', NULL, 1),
(482651, 46429, 10145, '<td valign="top">This is rather blurry. Could benefit from some sharpness, and the light is a bit harsh as well.</td>', 'This is rather blurry. Could benefit from some sharpness, and the light is a bit harsh as well.', '2003-11-12 15:12:37.000000', NULL, 1),
