(485607, 46395, 13064, '<td valign="top">this works well in B&amp;W  nice composition...  Leads the eye through the image</td>', 'this works well in B&W  nice composition...  Leads the eye through the image', '2003-11-14 16:22:11.000000', NULL, 1),
(485609, 46574, 3569, '<td valign="top">the fill flash is somewhat distracting, but the sunset/rise is so dark, it may overall helped.</td>', 'the fill flash is somewhat distracting, but the sunset/rise is so dark, it may overall helped.', '2003-11-14 16:22:57.000000', NULL, 1),
(485610, 46660, 13064, '<td valign="top">it was a pity the lights were on inside...  detracts form a wonderful image and thought process 8</td>', 'it was a pity the lights were on inside...  detracts form a wonderful image and thought process 8', '2003-11-14 16:23:20.000000', NULL, 1),
