(485967, 45822, 9904, '<td valign="top">Been Drinking ?</td>', 'Been Drinking ?', '2003-11-14 22:58:17.000000', NULL, 1),
(485970, 46438, 14193, '<td valign="top">Gorgeous photo, but you may want to crop it to cut out the perspective of the airplane and just have the view outside. The airplane takes away from the majesty of the shot.</td>', 'Gorgeous photo, but you may want to crop it to cut out the perspective of the airplane and just have the view outside. The airplane takes away from the majesty of the shot.', '2003-11-14 23:09:03.000000', NULL, 1),
