(486093, 46167, 11248, '<td valign="top">Great composition and lighting. Very good job.</td>', 'Great composition and lighting. Very good job.', '2003-11-15 06:25:48.000000', NULL, 1),
(486094, 46131, 11248, '<td valign="top">Very well seen and executed.</td>', 'Very well seen and executed.', '2003-11-15 06:26:34.000000', NULL, 1),
(486095, 46551, 11248, '<td valign="top">Wonderful scene and great picture even if it looks to be a lake, not a river.</td>', 'Wonderful scene and great picture even if it looks to be a lake, not a river.', '2003-11-15 06:27:31.000000', NULL, 1),
